};

// Inisialisasi tabel site_settings jika belum ada
async function initSettingsTable() {
  try {
    await db.execute(`
      CREATE TABLE IF NOT EXISTS site_settings (
        setting_id INT AUTO_INCREMENT PRIMARY KEY,
        setting_key VARCHAR(100) NOT NULL UNIQUE,
        setting_value TEXT NULL,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
      )
    `);
  } catch (err) {
    // Database fallback
  }
}
initSettingsTable();

// --- Rute GET /api/settings ---
app.get('/api/settings', async (req, res) => {
  try {
    let settings = { ...mockSiteSettings };
    try {
      const [rows] = await db.execute('SELECT setting_key, setting_value FROM site_settings');
      if (rows && rows.length > 0) {
        rows.forEach(r => {
          settings[r.setting_key] = r.setting_value;
        });
      }
    } catch (dbErr) {
      // gunakan mock fallback
    }
    res.status(200).json({ status: 'success', data: settings });
  } catch (error) {
    console.error('Error fetching settings:', error);
    res.status(500).json({ status: 'error', message: 'Gagal mengambil pengaturan situs.' });
